"""Domain model for user and global alerts."""

from django.conf import settings
from django.db import models

from apps.countries.models import Country


class AlertType(models.TextChoices):
    """Categories of alerts generated by the platform."""

    RIESGO = "RIESGO", "Riesgo"
    TIPO_CAMBIO = "TIPO_CAMBIO", "Tipo de cambio"
    INDICADOR = "INDICADOR", "Indicador"


class AlertSeverity(models.TextChoices):
    """Severity levels for alerts."""

    INFO = "INFO", "Info"
    WARNING = "WARNING", "Warning"
    CRITICAL = "CRITICAL", "Critical"


class Alert(models.Model):
    """Alert targeted to a user or broadcast globally when usuario is null."""

    usuario = models.ForeignKey(
        settings.AUTH_USER_MODEL,
        on_delete=models.CASCADE,
        related_name="alertas",
        verbose_name="usuario",
        null=True,
        blank=True,
    )
    pais = models.ForeignKey(
        Country,
        on_delete=models.CASCADE,
        related_name="alertas",
        verbose_name="país",
    )
    tipo_alerta = models.CharField(
        "tipo de alerta",
        max_length=20,
        choices=AlertType.choices,
    )
    severidad = models.CharField(
        "severidad",
        max_length=20,
        choices=AlertSeverity.choices,
    )
    titulo = models.CharField("título", max_length=200)
    mensaje = models.TextField("mensaje")
    leida = models.BooleanField("leída", default=False)
    fecha_creacion = models.DateTimeField("fecha de creación", auto_now_add=True)

    class Meta:
        db_table = "alertas"
        verbose_name = "alerta"
        verbose_name_plural = "alertas"
        ordering = ["-fecha_creacion"]
        indexes = [
            models.Index(fields=["usuario", "leida"], name="idx_alerta_usuario_leida"),
            models.Index(fields=["tipo_alerta", "severidad"], name="idx_alerta_tipo_sev"),
            models.Index(fields=["pais"], name="idx_alerta_pais"),
        ]

    def __str__(self):
        return f"[{self.severidad}] {self.titulo}"
